// ================= MINIJUEGOS DE ACTIVIDAD =================
def('act','Pesca con tensión','El pez tira con fuerza variable y debes recoger sedal sin pasarte de tensión (se rompe) ni quedarte corto (se escapa).','Stardew Valley, Animal Crossing, Zelda: Ocarina of Time','Toca para lanzar; mantén para recoger cuando pique.','A:Recoger',()=>{
let st=0,tn=.5,d=1,pull=0,pt=0,msg='Toca para lanzar',w=0,caught=0;return dt=>{if(st==0){if(PT||hit('a')){st=1;w=R(1,3);msg='Esperando que pique…'}}else if(st==1){w-=dt;if(w<=0){st=2;tn=.45;d=1;msg='¡Pica! Mantén para recoger'}}
else{pt-=dt;if(pt<=0){pull=R(0,1.4);pt=R(.4,1.2)}const reel=key('a')||P.down;tn+=((reel?.55:-.35)+pull*.5-.25)*dt;if(reel)d-=dt*.12*(1-pull*.5);if(tn>=1){st=0;msg='¡Se rompió el sedal! Toca para lanzar'}else if(tn<=0){st=0;msg='Se escapó… toca para lanzar'}else if(d<=0){st=0;caught++;msg='¡Pez capturado! ('+caught+')';shake(2)}}
clr('#0e3a5a');rect(0,0,320,40,'#7ec8e3');rect(10,20,30,20,'#8d6e4c');const fx=60+d*220,fy=st==2?120+Math.sin(T*8)*pull*8:110;if(st>0){line(40,22,fx,fy,'#fff',1);circ(fx,fy,st==2?7:3,st==2?OR:RD)}
if(st==2){rect(300,40,12,140,'#262a3d');rect(300,40+140*.15,12,140*.6,'#7ae58244');rect(298,40+140*(1-tn)-2,16,4,tn>.85||tn<.25?RD:Y);bar(60,188,220,4,1-d,GR)}txt(msg,8,52,11)}});

def('act','Forzar cerraduras','Buscas el ángulo correcto moviendo la ganzúa mientras giras la cerradura; si fuerzas en mal ángulo, la ganzúa se desgasta.','Skyrim, Fallout 3, Fallout 4','Mueve la ganzúa tocando arriba (o ◀▶) y mantén abajo (o A) para girar.','H|A:Girar',()=>{
let sw=R(-1.2,1.2),pa=0,tr=0,dur=1,ok=0,msg='';return dt=>{const turning=key('a')||P.down&&P.y>140;if(!turning){if(key('l'))pa-=dt*1.5;if(key('r'))pa+=dt*1.5;if(P.down&&P.y<=140)pa=(P.x-160)/100;pa=cl(pa,-1.5,1.5)}const close=1-Math.min(1,Math.abs(pa-sw)/.9),max=close>.85?1:close;
if(turning){if(tr<max)tr=Math.min(max,tr+dt*1.2);else{dur-=dt*.6;shake(1)}}else tr=Math.max(0,tr-dt*2);if(tr>=1){ok++;msg='¡Abierta!';sw=R(-1.2,1.2);tr=0}if(dur<=0){msg='¡Ganzúa rota!';dur=1;tr=0}
clr();circ(160,100,50,'#6b7290');circ(160,100,38,'#3a3f5c');G.save();G.translate(160,100);G.rotate(tr*Math.PI/2);rect(-4,-30,8,60,'#1b1b1b');G.restore();G.save();G.translate(160,100);G.rotate(pa-Math.PI/2);rect(0,-1.5,70,3,'#ddd');G.restore();rect(0,140,320,60,'#ffffff08');bar(8,8,80,5,dur,dur>.3?GR:RD);txt('Ganzúa',94,10,9,GY);txt('Abiertas: '+ok+'  '+msg,8,24,10,Y);txt('Zona de giro',160,186,10,GY,'center')}});

def('act','Conectar cables','Unir cada extremo con su pareja de color arrastrando. Tarea sencilla que funciona como pausa o mini-reto.','Among Us, Five Nights at Freddy’s (en parte), Lethal Company','Arrastra desde cada cable de la izquierda hasta el de su color.','',()=>{
const C=[RD,BL,Y,PU];let L,Rr,con,drag=null;const nw=()=>{L=[0,1,2,3].sort(()=>Math.random()-.5);Rr=[0,1,2,3].sort(()=>Math.random()-.5);con={}};nw();
return dt=>{if(PT){const i=L.findIndex((c,k)=>dist(P.x,P.y,30,35+k*40)<20);if(i>=0)drag=i}if(drag!==null&&!P.down){const j=Rr.findIndex((c,k)=>dist(P.x,P.y,290,35+k*40)<22);if(j>=0&&Rr[j]==L[drag])con[drag]=j;drag=null}const done=Object.keys(con).length==4;if(done&&PT&&P.x>100&&P.x<220)nw();
clr('#2a2d36');L.forEach((c,k)=>rect(10,28+k*40,30,14,C[c]));Rr.forEach((c,k)=>rect(280,28+k*40,30,14,C[c]));for(const i in con)line(40,35+i*40,280,35+con[i]*40,C[L[i]],6);if(drag!==null&&P.down)line(40,35+drag*40,P.x,P.y,C[L[drag]],6);txt(done?'¡Tarea completada! Toca en el centro para otra':'Une los cables por color',160,190,11,done?GR:GY,'center')}});

def('act','Cocinar en su punto','Controlar el tiempo de cocción de cada cara: muy poco queda crudo, demasiado se quema.','Overcooked, Cooking Mama, Monster Hunter (filete)','Toca arriba para dar la vuelta y abajo para servir.','',()=>{
let side=0,sides=[0,0],res='',st=1;const sc=v=>v<.4?'cruda':v<.6?'poco hecha':v<.8?'al punto':v<1?'muy hecha':'quemada',col=v=>v<.4?'#d6455d':v<.6?'#b5534a':v<.8?'#8a5a3c':v<1?'#5a3a22':'#1a1a1a';
return dt=>{if(st){sides[side]+=dt*.18;if(hit('a')||PT&&P.y<150)side^=1;if(hit('b')||PT&&P.y>=150){res='Cara A: '+sc(sides[0])+' · Cara B: '+sc(sides[1]);st=0}}else if(PT||hit('a')){sides=[0,0];side=0;st=1;res=''}
clr();rect(80,110,160,40,'#333');circ(160,105,40,col(sides[side]));ring(160,105,40,col(sides[side^1]),3);if(st)for(let i=0;i<3;i++)circ(130+i*30,60-((T*30+i*20)%30),2,'#ffffff55');[0,1].forEach(i=>{txt('Cara '+'AB'[i],8,14+i*16,10,i==side?Y:GY);bar(56,10+i*16,100,6,sides[i]/1.1,col(sides[i]))});rect(56+100*.6/1.1,6,100*.2/1.1,28,'#7ae58233');
if(st){rect(0,150,320,50,'#ffffff08');txt('Toca arriba: dar la vuelta · toca aquí: servir',160,175,10,WH,'center')}else txt(res,160,175,10,Y,'center')}});

def('act','Cortar con gestos','Deslizar el dedo traza un corte que divide los objetos que cruza; hay trampas que no se deben tocar.','Fruit Ninja, Metal Gear Rising (corte libre), Wii Sports Resort','Desliza el dedo sobre las frutas; evita las bombas.','',()=>{
let F=[],t=0,tr=[],sc=0,ms=0;const fx=PX();return dt=>{t-=dt;if(t<=0){t=R(.4,.9);F.push({x:R(60,260),y:210,vx:R(-40,40),vy:-R(260,330),b:Math.random()<.15,c:[RD,OR,GR,Y][RI(0,3)]})}if(P.down)tr.push([P.x,P.y,.15]);for(const p of tr)p[2]-=dt;tr=tr.filter(p=>p[2]>0);
for(const f of F){f.vy+=300*dt;f.x+=f.vx*dt;f.y+=f.vy*dt;if(tr.length>1){const a=tr[tr.length-2],b=tr[tr.length-1];if(dist(a[0],a[1],b[0],b[1])>4&&segD(f.x,f.y,a[0],a[1],b[0],b[1])<12){f.d=1;if(f.b){sc=0;shake(8);fx.add(f.x,f.y,30,WH,200)}else{sc++;fx.add(f.x,f.y,12,f.c,120)}}}if(f.y>220&&f.vy>0){f.d=1;if(!f.b)ms++}}F=F.filter(f=>!f.d);
clr('#2b1d14');for(const f of F){circ(f.x,f.y,10,f.b?'#222':f.c);if(f.b)circ(f.x+6,f.y-8,3,RD)}fx.run(dt,300);G.strokeStyle=WH;G.lineWidth=3;G.beginPath();tr.forEach((p,i)=>i?G.lineTo(p[0],p[1]):G.moveTo(p[0],p[1]));G.stroke();txt('Cortes '+sc+' · caídas '+ms,8,10)}});

def('act','Trazar con precisión','Seguir un recorrido marcado con el dedo; la puntuación depende de cuánto te desvías.','Okami (pincel celestial), Brain Age, Harry Potter (hechizos)','Traza la línea punteada sin levantar el dedo, de verde a rojo.','',()=>{
let path,prog=0,err=0,n=0,done='';const nw=()=>{path=[];const k=RI(0,2);for(let i=0;i<=60;i++){const t=i/60,z=(t*4)%1;path.push(k==0?[40+t*240,100+Math.sin(t*6.283*1.5)*50]:k==1?[160+Math.cos(t*6.283)*70,100+Math.sin(t*6.283)*70]:[40+t*240,100+(z<.5?z*2:2-z*2)*80-40])}prog=0;err=0;n=0;done=''};nw();
return dt=>{if(P.down&&!done){let best=1e9;for(let i=Math.max(0,prog-2);i<Math.min(61,prog+6);i++){const d=dist(P.x,P.y,path[i][0],path[i][1]);if(d<best)best=d;if(d<16&&i>prog)prog=i}if(prog>0){err+=Math.min(best,30);n++}if(prog>=60)done='Precisión: '+Math.max(0,Math.round(100-err/n*4))+'% · toca para otra'}if(PR&&!done)prog=0;if(done&&PT)nw();
clr();G.setLineDash([4,5]);G.strokeStyle=GY;G.lineWidth=2;G.beginPath();path.forEach((p,i)=>i?G.lineTo(p[0],p[1]):G.moveTo(p[0],p[1]));G.stroke();G.setLineDash([]);G.strokeStyle=Y;G.lineWidth=4;G.beginPath();path.slice(0,prog+1).forEach((p,i)=>i?G.lineTo(p[0],p[1]):G.moveTo(p[0],p[1]));G.stroke();circ(path[0][0],path[0][1],6,GR);circ(path[60][0],path[60][1],6,RD);txt(done,8,190,11,Y)}});

def('act','Golpear al topo','Objetivos que aparecen y desaparecen rápido en posiciones fijas; algunos valen más.','Whac-A-Mole, Mario Party, WarioWare','Toca a los topos antes de que se escondan. Los dorados valen 5.','',()=>{
const Hs=[];for(let i=0;i<9;i++)Hs.push({x:70+(i%3)*90,y:52+Math.floor(i/3)*55,t:0,up:0,gold:0});let sc=0,tm=30,sp=0;
return dt=>{if(tm<=0){if(PT){tm=30;sc=0}}else{tm-=dt;sp-=dt;if(sp<=0){sp=R(.3,.8);const h=Hs[RI(0,8)];if(!h.up){h.up=1;h.t=R(.6,1.1);h.gold=Math.random()<.1}}for(const h of Hs)if(h.up){h.t-=dt;if(h.t<=0)h.up=0}if(PT)for(const h of Hs)if(h.up&&dist(P.x,P.y,h.x,h.y-10)<24){h.up=0;sc+=h.gold?5:1;shake(2)}}
clr('#3e6b3a');for(const h of Hs){G.save();G.beginPath();G.rect(h.x-30,h.y-40,60,40);G.clip();if(h.up){circ(h.x,h.y-10,16,h.gold?Y:'#8d6e4c');circ(h.x-6,h.y-14,2,BG);circ(h.x+6,h.y-14,2,BG)}G.restore();rect(h.x-22,h.y,44,8,'#2a1d14')}txt('Puntos '+sc,8,10);txt(Math.max(0,tm).toFixed(0)+' s',312,10,11,WH,'right');if(tm<=0)txt('¡Tiempo! Toca para repetir',160,192,12,Y,'center')}});

def('act','Rascar y excavar','Retirar capas poco a poco para descubrir lo que hay debajo con cuidado.','Pokémon Diamante (subsuelo), Animal Crossing (fósiles), Ultima Ratio','Frota con el dedo para desenterrar el tesoro.','',()=>{
const w=64,h=40,S=5;let g,tr,found=0,done=false;const nw=()=>{g=new Float32Array(w*h).fill(1);tr={x:RI(10,54)*S,y:RI(10,30)*S,k:RI(0,2)};done=false};nw();
return dt=>{if(P.down){const cx=P.x/S,cy=P.y/S;for(let a=-3;a<=3;a++)for(let b=-3;b<=3;b++){const x=Math.floor(cx+a),y=Math.floor(cy+b);if(x>=0&&x<w&&y>=0&&y<h&&a*a+b*b<10)g[y*w+x]=Math.max(0,g[y*w+x]-dt*3)}}
let rev=0,tot=0;for(let a=-4;a<=4;a++)for(let b=-4;b<=4;b++){const x=Math.floor(tr.x/S)+a,y=Math.floor(tr.y/S)+b;if(x>=0&&x<w&&y>=0&&y<h){tot++;if(g[y*w+x]<.3)rev++}}if(!done&&rev/tot>.75){done=true;found++}if(done&&PT&&dist(P.x,P.y,tr.x,tr.y)>40)nw();
clr('#c9a36b');if(tr.k==0){line(tr.x-14,tr.y,tr.x+14,tr.y,'#f4f1ea',6);circ(tr.x-15,tr.y-3,4,'#f4f1ea');circ(tr.x-15,tr.y+3,4,'#f4f1ea');circ(tr.x+15,tr.y-3,4,'#f4f1ea');circ(tr.x+15,tr.y+3,4,'#f4f1ea')}else if(tr.k==1){G.fillStyle=PU;G.beginPath();G.moveTo(tr.x,tr.y-14);G.lineTo(tr.x+12,tr.y);G.lineTo(tr.x,tr.y+14);G.lineTo(tr.x-12,tr.y);G.fill()}else{circ(tr.x,tr.y,12,Y);ring(tr.x,tr.y,8,OR,2)}
for(let i=0;i<w*h;i++)if(g[i]>.02){G.fillStyle='rgba(92,64,40,'+g[i]+')';G.fillRect((i%w)*S,Math.floor(i/w)*S,S,S)}txt(done?'¡Hallazgo! Toca fuera para otro':'Encontrados: '+found,8,10,10,done?GR:WH)}});

def('act','Fotografía','Encuadrar un objetivo en movimiento y disparar en el momento justo; se puntúa el centrado.','Pokémon Snap, Beyond Good & Evil, Fatal Frame','Toca cuando el pájaro esté en el centro del visor.','A:Foto',()=>{
let bx=0,by=0,shots=[],flash=0;return dt=>{bx=160+Math.sin(T*1.3)*120;by=100+Math.sin(T*2.1)*60;flash-=dt;if(PT||hit('a')){shots.unshift(Math.max(0,Math.round(100-dist(160,100,bx,by)*1.5)));if(shots.length>5)shots.pop();flash=.15}
clr('#7ec8e3');rect(0,150,320,50,'#4caf50');circ(bx,by,10,OR);G.fillStyle=OR;G.beginPath();G.moveTo(bx-8,by);G.lineTo(bx-20,by-8+Math.sin(T*20)*6);G.lineTo(bx-8,by+4);G.fill();circ(bx+4,by-3,2,BG);srect(100,60,120,80,WH,2);line(150,100,170,100,WH,1);line(160,90,160,110,WH,1);if(flash>0)rect(0,0,320,200,'#ffffffcc');txt('Fotos: '+(shots.map(s=>s+' pts').join(' · ')||'ninguna'),8,190,10,BG)}});

def('act','Lanzar con pulso tembloroso','La mira oscila sola y hay que elegir el momento; contener la respiración la estabiliza durante poco tiempo.','Sniper Elite, Call of Duty (contener respiración), Dardos de Wii Party','B contiene la respiración; A o toca para lanzar el dardo.','A:Lanzar|B:Respirar',()=>{
let sc=[],stam=1,fl=null;return dt=>{const br=key('b')&&stam>0;if(br)stam=Math.max(0,stam-dt*.5);else stam=Math.min(1,stam+dt*.2);const amp=br?4:22,ax=160+Math.sin(T*1.7)*amp+Math.sin(T*3.1)*amp*.5,ay=100+Math.cos(T*1.3)*amp+Math.sin(T*2.3)*amp*.4;
if((hit('a')||PT)&&!fl)fl={x:ax,y:ay,t:.25};if(fl){fl.t-=dt;if(fl.t<=0&&!fl.done){const d=dist(fl.x,fl.y,160,100);sc.unshift(d<6?50:d<20?25:d<40?10:d<60?5:0);if(sc.length>6)sc.pop();fl.done=1}if(fl.t<-.6)fl=null}
clr('#2a1d14');[60,40,20,6].forEach((r,i)=>circ(160,100,r,['#e9e3d0',RD,'#e9e3d0',GR][i]));if(fl&&fl.done)circ(fl.x,fl.y,3,'#222');ring(ax,ay,8,Y,2);line(ax-12,ay,ax+12,ay,Y,1);line(ax,ay-12,ax,ay+12,Y,1);bar(8,186,80,6,stam,BL);txt('Aliento',94,189,9,GY);txt(sc.join(' · '),8,10,10,Y)}});

def('act','Máquina de garra','Colocas la garra y la dejas caer; el agarre es imperfecto y el premio puede soltarse en el camino.','Máquinas de feria, Animal Crossing, Mario Party','Mueve la garra con ◀▶ o tocando arriba; A o toca abajo para bajarla.','H|A:Bajar',()=>{
let cx=160,st=0,cy=20,got=null,pr=[],sc=0;const nw=()=>{pr=[];for(let i=0;i<7;i++)pr.push({x:R(60,290),c:[RD,BL,Y,PU,GR][RI(0,4)]})};nw();
return dt=>{if(st==0){cx=cl(cx+((key('r')?1:0)-(key('l')?1:0))*90*dt,30,290);if(P.down&&P.y<140)cx=lerp(cx,P.x,.15);if(hit('a')||PT&&P.y>=140)st=1}else if(st==1){cy+=90*dt;if(cy>=150){st=2;const p=pr.find(p=>Math.abs(p.x-cx)<10);if(p&&Math.random()<1-Math.abs(p.x-cx)/12){got=p;pr.splice(pr.indexOf(p),1)}}}
else if(st==2){cy-=70*dt;if(got&&Math.random()<dt*.25){got.x=cx;pr.push(got);got=null}if(cy<=20){cy=20;st=3}}else{cx-=120*dt;if(cx<=30){cx=30;if(got){sc++;got=null}st=0;if(pr.length<3)nw()}}
clr('#1b2340');rect(10,175,300,25,'#3a3f5c');rect(15,150,30,25,'#111');for(const p of pr)circ(p.x,166,9,p.c);line(cx,0,cx,cy,'#aaa',2);const op=st==1?6:3;line(cx,cy,cx-10-op,cy+14,'#ddd',3);line(cx,cy,cx+10+op,cy+14,'#ddd',3);if(got)circ(cx,cy+18,9,got.c);txt('Premios: '+sc,8,10,11,Y);txt('Toca aquí para bajar la garra',160,145,9,GY,'center')}});

// ================= NARRATIVA Y SOCIAL =================
def('nar','Diálogo con opciones','Conversaciones en las que eliges qué responder y cada opción lleva a una rama distinta. El texto aparece letra a letra.','Mass Effect, Disco Elysium, Monkey Island','Toca una respuesta.','',()=>{
const D={start:['Tabernera','¿Qué te trae por aquí, forastero?',[['Busco trabajo','job'],['Solo una bebida','drink'],['(Amenazar) Dame tu oro','threat']]],job:['Tabernera','Hay lobos en el bosque. El alcalde paga bien por ellos.',[['Acepto','accept'],['¿Cuánto paga?','pay']]],pay:['Tabernera','Cincuenta monedas. Más si vuelves de una pieza.',[['Acepto','accept'],['Es poco','start']]],drink:['Tabernera','Invita la casa. Pareces cansado.',[['Gracias','start']]],threat:['Tabernera','¡Guardias! (Tu reputación en el pueblo baja)',[['Huir','start']]],accept:['Tabernera','Buena suerte. La vas a necesitar.',[['Volver a empezar','start']]]};let n='start',ty=0;
return dt=>{const d=D[n];ty+=dt*40;if(PT&&ty<d[1].length&&P.y<95)ty=999;clr('#1a1424');circ(40,46,22,'#c77d4f');rect(20,68,40,30,'#7a3b5c');rect(76,14,238,74,'#0009');srect(76.5,14.5,237,73,WH);txt(d[0],86,26,10,Y);wrap(d[1].slice(0,Math.floor(ty)),86,44,220,11);
let pk=null;if(ty>=d[1].length)d[2].forEach((o,i)=>{if(btn(16,100+i*32,288,26,o[0]))pk=o[1]});if(pk){n=pk;ty=0}}});

def('nar','Afinidad con personajes','Cada personaje tiene una relación contigo que sube o baja con regalos y decisiones, y desbloquea contenido.','Stardew Valley, Persona (vínculos), Fire Emblem: Three Houses','Toca a un personaje y hazle regalos.','',()=>{
const NP=[{n:'Lía',likes:'Flor',hates:'Pez',a:30,c:PU},{n:'Bruno',likes:'Pez',hates:'Libro',a:30,c:OR}],Gf=['Flor','Pez','Libro','Gema'];let sel=0,msg='';const ft=FT();
return dt=>{clr();NP.forEach((p,i)=>{const x=80+i*160;if(PT&&dist(P.x,P.y,x,56)<30)sel=i;circ(x,56,22,p.c);if(i==sel)ring(x,56,26,Y,2);txt(p.n,x,88,11,WH,'center');bar(x-40,96,80,6,p.a/100,RD);txt(p.a<20?'Distante':p.a<50?'Conocido':p.a<80?'Amigo':'Mejor amigo',x,110,9,GY,'center')});
let pk=-1;Gf.forEach((g,i)=>{if(btn(8+i*78,132,74,28,'Regalar '+g.toLowerCase()))pk=i});if(pk>=0){const p=NP[sel],g=Gf[pk],d=g==p.likes?15:g==p.hates?-12:4;p.a=cl(p.a+d,0,100);msg=p.n+(d>10?': «¡Me encanta!»':d<0?': «Puaj…»':': «Gracias.»');ft.add((d>0?'+':'')+d,80+sel*160,30,d>0?GR:RD)}ft.run(dt);txt(msg,8,182,11,Y)}});

def('nar','Reputación con facciones','Tus decisiones agradan a unos grupos y enfadan a otros; cada facción reacciona según su opinión de ti.','Fallout: New Vegas, Skyrim, The Outer Worlds','Elige en cada dilema y observa las barras.','',()=>{
const F=[['Gremio',Y],['Guardia',BL],['Ladrones',PU]],E=[['Un ladrón te ofrece mercancía robada.',[['Comprar',[0,-10,15]],['Denunciarlo',[0,15,-15]]]],['El gremio pide que subas los precios.',[['Aceptar',[15,0,-5]],['Negarte',[-15,5,5]]]],['Un guardia te pide un soborno.',[['Pagar',[-5,10,5]],['Delatarlo',[5,-15,0]]]],['Los ladrones planean robar al gremio.',[['Ayudarles',[-20,-10,20]],['Avisar al gremio',[15,5,-20]]]]],r=[0,0,0];let e=0;
return dt=>{clr();F.forEach((f,i)=>{const y=14+i*20;txt(f[0],8,y,10,f[1]);rect(80,y-5,180,10,'#262a3d');rect(170,y-5,1,10,WH);const v=r[i]*.9;rect(v>=0?170:170+v,y-4,Math.abs(v),8,v>=0?GR:RD);txt(r[i]>40?'Aliado':r[i]<-40?'Hostil':'Neutral',266,y,9,GY)});wrap(E[e][0],8,80,300,11);let pk=null;E[e][1].forEach((o,i)=>{if(btn(8+i*156,104,148,30,o[0]))pk=o});if(pk){pk[1].forEach((d,k)=>r[k]=cl(r[k]+d,-100,100));e=(e+1)%E.length}txt('Cada decisión agrada a unos y enfada a otros',8,184,10,GY)}});

def('nar','Decisiones con consecuencias','Elecciones con tiempo límite que el juego recuerda y que cambian el final o el trato de otros personajes.','The Walking Dead (Telltale), Until Dawn, Life is Strange','Elige antes de que se acabe el tiempo. No elegir también cuenta.','',()=>{
const Q=[['Tu compañero está herido y los enemigos se acercan.',['Cargar con él','Dejarlo atrás']],['Un niño roba pan en el mercado.',['Pagar el pan','Mirar a otro lado']],['El rey te ofrece un título a cambio de lealtad.',['Aceptar','Rechazar']]];let q=0,t=6,mem=[],note=0;
return dt=>{clr();if(q<Q.length){t-=dt;note-=dt;wrap(Q[q][0],12,30,296,13);bar(12,78,296,4,t/6,t<2?RD:Y);let pick=-1;Q[q][1].forEach((o,i)=>{if(btn(12+i*152,96,144,34,o))pick=i});if(t<=0)pick=2;if(pick>=0){mem.push(pick==2?'Dudaste y no hiciste nada':Q[q][1][pick]);q++;t=6;note=1.5}if(note>0)txt('Lo recordarán.',160,160,12,PU,'center')}
else{txt('Tu historia:',12,20,12,Y);mem.forEach((m,i)=>txt('• '+m,12,44+i*18,11));if(btn(100,150,120,28,'Empezar de nuevo')){q=0;mem=[];t=6}}}});

def('nar','Investigación y deducción','Reúnes pistas del escenario y las cruzas con los perfiles de los sospechosos para acusar al culpable.','Ace Attorney, Return of the Obra Dinn, L.A. Noire','Toca los brillos para hallar pistas y después acusa.','',()=>{
const Sp=[{n:'Mayordomo',c:OR,a:'zurdo · cocina · botas limpias'},{n:'Jardinera',c:GR,a:'diestra · jardín · botas con barro'},{n:'Sobrino',c:BL,a:'zurdo · jardín · botas con barro'}],clues=['El golpe lo dio alguien zurdo','Había huellas de barro junto al cuerpo','El crimen fue en el invernadero, junto al jardín'],spots=[{x:40,y:176},{x:160,y:184},{x:280,y:176}],found=[];let res='';
return dt=>{clr('#1a1424');spots.forEach((s,i)=>{if(!found.includes(i)){circ(s.x,s.y,6,'#ffd44755');ring(s.x,s.y,9+Math.sin(T*4)*2,Y);if(PT&&dist(P.x,P.y,s.x,s.y)<18)found.push(i)}});txt('Pistas ('+found.length+'/3):',8,10,10,Y);found.forEach((f,i)=>txt('• '+clues[f],8,24+i*12,9));
let pk=-1;Sp.forEach((s,i)=>{if(btn(8+i*104,66,100,30,'Acusar: '+s.n,s.c+'44'))pk=i;wrap(s.a,10+i*104,106,96,8,GY)});if(pk>=0)res=pk==2?'¡Correcto! Zurdo, con barro y en el jardín: el sobrino.':'No encaja con todas las pistas…';txt(res,8,150,10,pk==2||res[0]=='¡'?GR:RD)}});

// ================= SUPERVIVENCIA =================
def('sup','Hambre y sed','Necesidades que bajan con el tiempo y que hay que reponer comiendo y bebiendo; si llegan a cero, pierdes salud.','Don’t Starve, The Long Dark, Minecraft','Recoge comida (rojo) y bebe en el lago.','D',()=>{
let hu=1,th=1,hp=1,x=160,y=100,F=[],t=0;const Wt={x:270,y:150};return dt=>{hu-=dt*.05;th-=dt*.07;if(hu<=0||th<=0)hp-=dt*.1;else hp=Math.min(1,hp+dt*.02);if(hp<=0){hu=th=hp=1}hu=Math.max(0,hu);th=Math.max(0,th);t-=dt;if(t<=0&&F.length<4){F.push({x:R(20,230),y:R(50,180)});t=2}
const[dx,dy]=dir();x=cl(x+dx*90*dt,6,314);y=cl(y+dy*90*dt,6,194);for(let i=F.length;i--;)if(dist(x,y,F[i].x,F[i].y)<12){F.splice(i,1);hu=Math.min(1,hu+.3)}if(dist(x,y,Wt.x,Wt.y)<26)th=Math.min(1,th+dt*.5);
clr('#2b3a2a');circ(Wt.x,Wt.y,24,BL);for(const f of F)circ(f.x,f.y,5,RD);circ(x,y,7,'#e9c46a');[['Salud',hp,RD],['Hambre',hu,OR],['Sed',th,BL]].forEach((s,i)=>{txt(s[0],8,10+i*12,9,s[2]);bar(52,6+i*12,80,6,s[1],s[2])})}});

def('sup','Aguante (estamina)','Correr, esquivar o atacar consume una barra que se recupera al descansar. Si la vacías, quedas agotado un rato.','Dark Souls, Zelda: BotW, Elden Ring','◀▶ andar; mantén B para esprintar.','H|B:Esprintar',()=>{
let st=1,x=20,tired=0;return dt=>{const m=(key('r')?1:0)-(key('l')?1:0)||(P.down?1:0),sprint=(key('b')||P.down)&&!tired&&st>0&&m;if(sprint)st-=dt*.45;else st=Math.min(1,st+dt*(m?.12:.3));if(st<=0){tired=1;st=0}if(tired&&st>.4)tired=0;x+=m*(sprint?160:tired?30:70)*dt;if(x>330)x=-10;if(x<-10)x=330;
clr();rect(0,150,320,50,'#262a3d');rect(x-6,120+(sprint?Math.sin(T*30)*2:0),12,30,tired?GY:BL);bar(100,20,120,8,st,tired?RD:GR);txt(tired?'¡Agotado! Espera a recuperarte':'Aguante',160,40,10,tired?RD:WH,'center')}});

def('sup','Temperatura','El frío baja tu temperatura corporal fuera de las fuentes de calor; hay que mantener el fuego vivo con combustible.','The Long Dark, Frostpunk, Valheim','Junto al fuego, A echa leña. Ve a la derecha a por más leña.','H|A:Leña',()=>{
let x=40,tp=.7,fire=150,wood=3;const fx=60;return dt=>{x=cl(x+((key('r')?1:0)-(key('l')?1:0))*80*dt,6,314);const d=Math.abs(x-fx),warm=fire>0&&d<50;fire=Math.max(0,fire-dt*8);tp=cl(tp+(warm?.12:-.06)*dt,0,1);if(hit('a')&&d<30&&wood>0){wood--;fire=Math.min(200,fire+80)}if(x>290&&wood<5&&Math.random()<dt)wood++;if(tp<=0)tp=.7;
clr('#1a2236');for(let i=0;i<30;i++)circ((i*53+T*20)%320,(i*37+T*40)%200,1.5,'#ffffffaa');rect(0,170,320,30,'#dfe8f5');if(fire>0){const f=fire/200;G.fillStyle='rgba(255,159,67,0.12)';G.beginPath();G.arc(fx,165,50,0,7);G.fill();circ(fx,160,8+f*8,OR);circ(fx,155,4+f*5,Y)}rect(fx-10,166,20,4,'#5c3b1e');rect(300,140,14,30,'#5c3b1e');rect(x-5,145,10,25,tp<.3?BL:'#c77d4f');bar(8,8,100,6,tp,tp<.3?BL:OR);txt('Temperatura · leña '+wood,114,10,10)}});

def('sup','Oxígeno','Bajo el agua o en el espacio el aire se agota; hay que volver a la superficie antes de que se acabe.','Subnautica, Sonic (fases de agua), Dave the Diver','Bucea a por perlas y sube a respirar.','D',()=>{
let x=160,y=40,ox=1,bub=[],pearls=0,Pp={x:R(30,290),y:R(120,180)};return dt=>{const[dx,dy]=dir();x=cl(x+dx*70*dt,6,314);y=cl(y+dy*70*dt,30,194);const under=y>50;ox=under?ox-dt*.12:Math.min(1,ox+dt*.6);if(ox<=0){x=160;y=40;ox=1;shake(3)}if(dist(x,y,Pp.x,Pp.y)<12){pearls++;Pp={x:R(30,290),y:R(120,190)}}if(under&&Math.random()<dt*3)bub.push({x,y});for(const b of bub)b.y-=40*dt;bub=bub.filter(b=>b.y>50);
clr('#7ec8e3');rect(0,50,320,150,'#0e4a6e');rect(0,140,320,60,'#0a3550');circ(Pp.x,Pp.y,5,'#fff6e0');for(const b of bub)ring(b.x,b.y,2,'#ffffff88');circ(x,y,7,Y);bar(8,8,100,7,ox,ox<.3?RD:BL);txt('Oxígeno · perlas '+pearls,114,11,10,BG);if(ox<.3&&under)txt('¡Sube a respirar!',160,30,12,RD,'center')}});

def('sup','Cordura','Estar a oscuras o ver cosas horribles reduce la cordura y el juego empieza a mostrar alucinaciones.','Amnesia: The Dark Descent, Eternal Darkness, Darkest Dungeon','Quédate cerca de las luces para no perder la cabeza.','D',()=>{
let x=40,y=100,san=1;const L=[{x:60,y:60},{x:250,y:150}];return dt=>{const[dx,dy]=dir();x=cl(x+dx*70*dt,6,314);y=cl(y+dy*70*dt,6,194);const lit=L.some(l=>dist(x,y,l.x,l.y)<45);san=cl(san+(lit?.15:-.08)*dt,0,1);if(san<=0)san=1;const k=1-san;
clr('#0b0a10');for(const l of L){const g=G.createRadialGradient(l.x,l.y,2,l.x,l.y,45);g.addColorStop(0,'rgba(255,212,71,.45)');g.addColorStop(1,'rgba(255,212,71,0)');G.fillStyle=g;G.fillRect(l.x-45,l.y-45,90,90);circ(l.x,l.y,3,Y)}
if(k>.4)for(let i=0;i<Math.floor(k*8);i++){const a=T*.5+i;circ(x+Math.cos(a*1.7)*60,y+Math.sin(a*1.3)*40,3,'#ff000088')}G.save();if(k>.5)G.translate(R(-k,k)*3,R(-k,k)*3);circ(x,y,6,'#c9c3d6');G.restore();bar(8,8,100,6,san,san<.3?RD:PU);txt('Cordura',114,10,10,PU);if(k>.6)txt('¿Has oído eso?',160+R(-2,2),180,11,RD,'center')}});

def('sup','Linterna con batería','La luz es limitada: la batería se agota y hay que buscar pilas mientras exploras a oscuras.','Alan Wake, Five Nights at Freddy’s, Outlast','Cruceta para explorar; B enciende/apaga. Recoge pilas (verde).','D|B:Linterna',()=>{
let x=40,y=100,bat=1,on=true,a=0;const bs=[];for(let i=0;i<3;i++)bs.push({x:R(80,300),y:R(20,180)});
return dt=>{if(hit('b'))on=!on;const[dx,dy]=dir();if(dx||dy)a=Math.atan2(dy,dx);x=cl(x+dx*70*dt,6,314);y=cl(y+dy*70*dt,6,194);if(on)bat=Math.max(0,bat-dt*.06);for(let i=bs.length;i--;)if(dist(x,y,bs[i].x,bs[i].y)<12){bs.splice(i,1);bat=Math.min(1,bat+.4);bs.push({x:R(20,300),y:R(20,180)})}
clr('#2a2438');for(const b of bs)rect(b.x-4,b.y-6,8,12,GR);circ(x,y,6,WH);G.fillStyle='rgba(3,3,8,.96)';G.beginPath();G.rect(0,0,320,200);if(on&&bat>0&&!(bat<.2&&Math.random()<.2)){const r=110*Math.min(1,bat*2+.2);G.moveTo(x,y);G.arc(x,y,r,a-.5,a+.5);G.closePath();G.moveTo(x+12,y);G.arc(x,y,12,0,6.283)}G.fill('evenodd');txt('Batería',8,10,10,GY);bar(50,6,60,7,bat,bat<.25?RD:Y)}});

def('sup','Salud regenerativa o botiquines','Dos filosofías: la vida se recupera sola si evitas el daño un rato, o solo se cura con objetos que hay que encontrar.','Call of Duty (regeneración), DOOM y Half-Life (botiquines), Halo (mixto)','Esquiva los proyectiles. B cambia de sistema.','D|B:Sistema',()=>{
let m=0,hp=100,lh=0,kits=[],t=0,x=160,y=100,bs=[],bt=0;return dt=>{if(hit('b')){m^=1;hp=100;kits=[]}t-=dt;if(m&&t<=0&&kits.length<2){kits.push({x:R(20,300),y:R(30,180)});t=4}bt-=dt;if(bt<=0){bt=.5;const a=R(0,6.28);bs.push({x:160+Math.cos(a)*200,y:100+Math.sin(a)*200,a:a+Math.PI+R(-.3,.3)})}
const[dx,dy]=dir();x=cl(x+dx*100*dt,6,314);y=cl(y+dy*100*dt,6,194);for(const b of bs){b.x+=Math.cos(b.a)*120*dt;b.y+=Math.sin(b.a)*120*dt;if(dist(b.x,b.y,x,y)<8){b.d=1;hp-=15;lh=0;shake(2)}}bs=bs.filter(b=>!b.d&&dist(b.x,b.y,160,100)<260);lh+=dt;if(!m&&lh>2.5)hp=Math.min(100,hp+30*dt);for(let i=kits.length;i--;)if(dist(x,y,kits[i].x,kits[i].y)<12){kits.splice(i,1);hp=Math.min(100,hp+40)}if(hp<=0)hp=100;
clr();if(!m&&hp<60){G.fillStyle='rgba(255,0,0,'+(60-hp)/150+')';G.fillRect(0,0,320,200)}for(const k of kits){rect(k.x-7,k.y-7,14,14,WH);rect(k.x-1.5,k.y-5,3,10,RD);rect(k.x-5,k.y-1.5,10,3,RD)}for(const b of bs)circ(b.x,b.y,3,OR);circ(x,y,7,BL);bar(8,8,100,7,hp/100,hp<30?RD:GR);txt(m?'Sistema: botiquines':'Sistema: regeneración',114,11,10,Y)}});

// ================= SENSACIÓN DE JUEGO (GAME FEEL) =================
def('feel','Temblor de pantalla','Sacudir la cámara en impactos y disparos multiplica la sensación de potencia.','Vlambeer (Nuclear Throne), Hades, Gears of War','Toca para disparar. B activa o desactiva el temblor.','B:Temblor',()=>{
let on=1,bs=[],rec=0;const fx=PX();return dt=>{if(hit('b'))on^=1;rec=Math.max(0,rec-dt*60);if(PT||hit('a')){bs.push({x:50,vx:400});if(on){shake(4);rec=6}}for(const b of bs){b.x+=b.vx*dt;if(b.x>290){b.d=1;fx.add(290,100,on?20:4,OR,on?160:40);if(on)shake(7)}}bs=bs.filter(b=>!b.d);
clr();rect(290,60,20,80,RD);rect(20-rec,92,30,16,BL);for(const b of bs)circ(b.x,100,4,Y);fx.run(dt);txt('Temblor: '+(on?'SÍ':'NO'),8,10,11,on?GR:RD)}});

def('feel','Parada de impacto (hitstop)','El juego se congela unas centésimas al conectar un golpe. Parece un fallo, pero da peso y claridad al impacto.','Street Fighter, Monster Hunter, Celeste','Golpea con A. B activa o desactiva la pausa.','A:Golpe|B:Hitstop',()=>{
let on=1,stop=0,ex=200,evx=0,sw=0,fl=0;return dt=>{if(hit('b'))on^=1;if(stop>0){stop-=dt;dt=0}if((hit('a')||PT)&&sw<=0&&stop<=0){sw=.2;fl=.1;evx=on?260:180;if(on){stop=.09;shake(4)}}sw-=dt;fl-=dt;ex+=evx*dt;evx*=Math.pow(.01,dt);if(ex>280)ex=280;if(evx<5&&ex>200)ex-=40*dt;
clr();rect(0,160,320,40,'#262a3d');rect(ex-12,110,24,50,fl>0?WH:RD);rect(140,110,20,50,BL);if(sw>0){G.strokeStyle=fl>0?WH:'#ffffff88';G.lineWidth=5;G.beginPath();G.arc(150,135,40,-1,1);G.stroke()}txt('Parada de impacto: '+(on?'SÍ':'NO'),8,10,11,on?GR:RD)}});

def('feel','Estirar y aplastar','Deformar los objetos al acelerar y chocar los hace sentir elásticos y vivos. Principio clásico de la animación.','Super Meat Boy, Celeste, cualquier película de Pixar','Toca para impulsar la pelota. B activa o desactiva la deformación.','B:Deformar',()=>{
let on=1,y=60,vy=0,sq=1;return dt=>{if(hit('b'))on^=1;vy+=700*dt;y+=vy*dt;if(y>170){y=170;vy=-380;if(on)sq=.55}if(PT||hit('a'))vy=-380;sq=lerp(sq,on?cl(1+Math.abs(vy)/900,1,1.4):1,.15);const sx=on?1/sq:1,sy=on?sq:1;
clr();rect(0,186,320,14,'#3a3f5c');G.save();G.translate(160,y+16);G.scale(sx,sy);circ(0,-16,16,OR);circ(-5,-20,3,BG);circ(5,-20,3,BG);G.restore();txt('Deformación: '+(on?'SÍ':'NO'),8,10,11,on?GR:RD)}});

def('feel','Partículas de feedback','Polvo al aterrizar, chispas al golpear o huellas al correr: pequeñas partículas que confirman cada acción.','Ori, Celeste, Hollow Knight','Corre y salta. B activa o desactiva las partículas.','H|A:Saltar|B:Partículas',()=>{
let on=1,was=true;const S=lvl(),b=body(40,160),fx=PX();return dt=>{if(hit('b'))on^=1;walk(b);if(hit('a')&&b.g){b.vy=-320;if(on)fx.add(b.x+6,b.y+16,8,WH,60,.35)}phys(b,S,dt);if(b.g&&!was&&on)fx.add(b.x+6,b.y+16,14,'#b8bdd6',90,.4);if(on&&b.g&&Math.abs(b.vx)>10&&Math.random()<dt*14)fx.add(b.x+6-b.face*4,b.y+16,1,'#8a90ad',30,.3);was=b.g;
clr();drawS(S);fx.run(dt,-50);hero(b);txt('Partículas: '+(on?'SÍ':'NO'),8,10,11,on?GR:RD)}});

def('feel','Curvas de suavizado (easing)','La forma en que algo acelera y frena cambia por completo cómo se percibe el movimiento.','Interfaces de casi todos los juegos, Mario Kart (menús), Hearthstone','Toca para invertir el movimiento y compara las curvas.','A:Invertir',()=>{
const E=[['Lineal',t=>t],['Suave',t=>1-(1-t)**3],['Elástico',t=>t==0||t==1?t:Math.pow(2,-10*t)*Math.sin((t*10-.75)*2.094)+1],['Rebote',t=>{const n=7.5625,d=2.75;if(t<1/d)return n*t*t;if(t<2/d)return n*(t-=1.5/d)*t+.75;if(t<2.5/d)return n*(t-=2.25/d)*t+.9375;return n*(t-=2.625/d)*t+.984375}]];let t=0,d=1;
return dt=>{if(PT||hit('a'))d*=-1;t=cl(t+d*dt*1.1,0,1);clr();E.forEach((e,i)=>{const k=d>0?e[1](t):1-e[1](1-t),y=30+i*42;line(100,y,300,y,'#262a3d',2);rect(100+k*180,y-10,20,20,[BL,GR,PU,OR][i]);txt(e[0],8,y,10)})}});

def('feel','Cámara con zona muerta y anticipación','La cámara no persigue cada pequeño movimiento (zona muerta) y se adelanta en la dirección de avance para mostrar lo que viene.','Super Mario World, Hollow Knight, Celeste','Recorre el nivel. B cambia el tipo de cámara.','H|A:Saltar|B:Cámara',()=>{
const WW=1000,MD=['Fija al jugador','Zona muerta','Anticipación'],S=[{x:0,y:184,w:WW,h:16},{x:-10,y:-200,w:10,h:400},{x:WW,y:-200,w:10,h:400}];for(let i=0;i<12;i++)S.push({x:120+i*75,y:R(100,160),w:40,h:8});let m=1,cx=0;const b=body(100,160);
return dt=>{if(hit('b'))m=(m+1)%3;walk(b,150);if(hit('a')&&b.g)b.vy=-320;phys(b,S,dt);let tx=cx;if(m==0)tx=b.x-154;else if(m==1){const sx=b.x-cx;if(sx<120)tx=b.x-120;if(sx>190)tx=b.x-190}else tx=b.x-154+b.face*70;cx=m==0?tx:lerp(cx,tx,1-Math.pow(.02,dt));cx=cl(cx,0,WW-320);
clr();G.save();G.translate(-Math.round(cx),0);for(let i=0;i<WW;i+=50)line(i,0,i,184,'#1c2030',1);drawS(S.filter(s=>s.x+s.w>cx-20&&s.x<cx+340).map(s=>({...s,x:s.x})));hero(b);G.restore();if(m==1)srect(120,0,70,200,'#ffd44755',1);txt('Cámara: '+MD[m],8,10,11,Y)}});

def('feel','Paralaje','Capas de fondo que se desplazan a distintas velocidades crean ilusión de profundidad en un juego 2D.','Sonic, Rayman Legends, Hollow Knight','◀▶ o toca a los lados. B activa o desactiva el paralaje.','H|B:Paralaje',()=>{
let x=0,on=1;const Ls=[[.2,'#232a55',120,50,.012],[.5,'#323c78',145,30,.025],[1,'#454f94',172,10,.05]];return dt=>{if(hit('b'))on^=1;const m=(key('r')?1:0)-(key('l')?1:0)||(P.down?(P.x>160?1:-1):0);x+=m*120*dt;
clr('#0e1024');for(let i=0;i<30;i++)circ((((i*67-x*(on?.05:1))%320)+320)%320,(i*29)%100,1,WH);for(const l of Ls){const off=x*(on?l[0]:1);G.fillStyle=l[1];G.beginPath();G.moveTo(0,200);for(let sx=0;sx<=320;sx+=6)G.lineTo(sx,l[2]-Math.abs(Math.sin((sx+off)*l[4]))*l[3]);G.lineTo(320,200);G.fill()}for(let k=0;k<8;k++){const sx=(((k*60-x)%480)+480)%480-80;rect(sx,160,6,22,'#2a2e44')}rect(156,158,10,16,Y);txt('Paralaje: '+(on?'SÍ':'NO'),8,10,11,on?GR:RD)}});

def('feel','Zoom dinámico','La cámara se aleja o se acerca automáticamente para encuadrar a todos los jugadores o la acción importante.','Super Smash Bros., TowerFall, LittleBigPlanet','Aléjate del punto rojo con la cruceta. B activa o desactiva el zoom.','D|B:Zoom',()=>{
let on=1;const a={x:100,y:100},c={x:220,y:100,t:0};return dt=>{if(hit('b'))on^=1;const[dx,dy]=dir();a.x+=dx*120*dt;a.y+=dy*120*dt;c.t+=dt;c.x=160+Math.cos(c.t*.7)*200;c.y=100+Math.sin(c.t*1.1)*120;const mx=on?(a.x+c.x)/2:a.x,my=on?(a.y+c.y)/2:a.y,z=on?1/Math.max(Math.abs(a.x-c.x)/260,Math.abs(a.y-c.y)/150,1):1;
clr();G.save();G.translate(160,100);G.scale(z,z);G.translate(-mx,-my);for(let i=-800;i<=1200;i+=40){line(i,-800,i,1000,'#1c2030',1);line(-800,i,1200,i,'#1c2030',1)}circ(a.x,a.y,8,BL);circ(c.x,c.y,8,RD);G.restore();txt('Zoom dinámico: '+(on?'SÍ':'NO'),8,10,11,on?GR:RD)}});

